    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)

        # Transform each element: nums[i] - i
        transformed = [nums[i] - i for i in range(n)]

        # Coordinate compression
        unique_vals = sorted(set(transformed))
        val_to_idx = {val: idx for idx, val in enumerate(unique_vals)}

        size = len(unique_vals)

        # Segment tree for maximum range queries
        tree = [float('-inf')] * (4 * size)

        def update(pos, val, node=0, left=0, right=size-1):
            """Update segment tree at position pos with value val"""
            if left == right:
                tree[node] = max(tree[node], val)
                return

            mid = (left + right) // 2
            if pos <= mid:
                update(pos, val, 2 * node + 1, left, mid)
            else:
                update(pos, val, 2 * node + 2, mid + 1, right)

            tree[node] = max(tree[2 * node + 1], tree[2 * node + 2])

        def query(qleft, qright, node=0, left=0, right=size-1):
            """Query maximum value in range [qleft, qright]"""
            if qright < left or right < qleft:
                return float('-inf')
            if qleft <= left and right <= qright:
                return tree[node]

            mid = (left + right) // 2
            left_val = query(qleft, qright, 2 * node + 1, left, mid)
            right_val = query(qleft, qright, 2 * node + 2, mid + 1, right)
