    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0

        # Check every possible subarray to remove
        for i in range(n):  # start of removal (inclusive)
            for j in range(i, n):  # end of removal (inclusive)
                # After removing [i, j], check if remaining is strictly increasing
                valid = True

                # Check left part [0, i-1] - if not empty, must be strictly increasing
                if i > 0:
                    for k in range(1, i):
                        if nums[k-1] >= nums[k]:
                            valid = False
                            break

                # Check right part [j+1, n-1] - if not empty, must be strictly increasing
                if valid and j < n - 1:
                    for k in range(j + 1, n - 1):
                        if nums[k] >= nums[k + 1]:
                            valid = False
                            break

                # If both parts exist, check transition from left to right
                if valid and i > 0 and j < n - 1:
                    if nums[i - 1] >= nums[j + 1]:
                        valid = False

                if valid:
                    total += 1

        return total

